"""Fetch maps engineer monthly comments without requiring AI regeneration."""
import os,json,subprocess,tempfile
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory(prefix='cfs-comment-headings-') as tmp:
 fixture=Path(tmp)/'data.json';data=json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify(require("./scripts/fixture").seed()))'],cwd=ROOT));release=next(v for k,v in data['docs'].items() if k.startswith('release:'));epic_id=release['epicIds'][0];raw='November comments - \r\nImplementation review is in progress.\r\nUpcoming implementation -\r\n1. Validate broker routing.\r\n================================\r\nSeptember comments -\r\nDesign finalized.';data['remote'][epic_id]['comments']=raw;fixture.write_text(json.dumps(data))
 server=subprocess.Popen(['node','server.js','--fixture'],cwd=ROOT,env={**os.environ,'PORT':'8414','CFS_FIXTURE_FILE':str(fixture)},stdout=subprocess.PIPE,text=True)
 try:
  assert 'Release Review' in server.stdout.readline()
  with sync_playwright() as p:
   b=p.chromium.launch();page=b.new_page(viewport={'width':1440,'height':1000});actions=[];page.on('request',lambda r:actions.append(r.post_data_json.get('action')) if r.method=='POST' and r.url.endswith('/api/handler') else None);page.add_init_script('window.aiCalls=0;window.AppletAI={isAvailable:()=>true,complete:async()=>{window.aiCalls++;throw Error("AI must not be required to fetch comments")}}');page.goto('http://127.0.0.1:8414');expect(page.locator('#epic-count')).to_have_text('6');page.locator('#fetch-button').click();expect(page.locator('#fetch-button')).to_be_enabled(timeout=20000);page.locator('[data-epic-preview="'+epic_id+'"]').locator('.epic-expand-toggle').click();detail=page.locator('#epic-details-'+epic_id);expect(detail.locator('.month-cell.current .update-text')).to_have_text('Implementation review is in progress. Upcoming implementation - 1. Validate broker routing.');expect(detail.locator('[data-month="2026-09"] .update-text')).to_have_text('Design finalized.');assert page.evaluate('window.aiCalls')==0;assert 'monthly-summary' not in actions;after=json.loads(fixture.read_text());assert after['remote'][epic_id]['comments']==raw;assert after['docs']['epic:'+epic_id]['comments']==raw;page.reload();expect(page.locator('#epic-count')).to_have_text('6');page.locator('[data-epic-preview="'+epic_id+'"]').locator('.epic-expand-toggle').click();expect(page.locator('#epic-details-'+epic_id+' .month-cell.current .update-text')).to_contain_text('Implementation review is in progress.');b.close();print('Comment-heading browser checks passed: manual Fetch populates November/September, shared reload retains updates, no AI or GUS comment writes.')
 finally:server.terminate();server.wait(timeout=10)
